package com.campusmart.service;
import com.campusmart.entity.*;import com.campusmart.repository.*;import com.campusmart.dto.ProductDtos;import org.springframework.stereotype.Service;import java.math.BigDecimal;import java.util.*;
@Service public class ProductService{private final ProductRepository products;private final CategoryRepository categories;private final UserService users;public ProductService(ProductRepository p,CategoryRepository c,UserService u){products=p;categories=c;users=u;}public List<Product>search(String q,String category,Product.Condition condition,BigDecimal max){return products.search(q==null||q.isBlank()?null:q,category,condition,max);}public Product get(Long id){return products.findById(id).orElseThrow(()->new IllegalArgumentException("Product not found"));}public Product create(ProductDtos.Create d,Long userId){Product p=new Product();apply(p,d,userId);return products.save(p);}public Product update(Long id,ProductDtos.Create d,Long userId,boolean admin){Product p=get(id);if(!admin&&!p.getSeller().getId().equals(userId))throw new IllegalArgumentException("You can edit only your own products");apply(p,d,userId);return products.save(p);}private void apply(Product p,ProductDtos.Create d,Long uid){p.setName(d.name().trim());p.setDescription(d.description().trim());p.setCategory(categories.findById(d.categoryId()).orElseThrow(()->new IllegalArgumentException("Category not found")));p.setPrice(d.price());p.setCondition(d.condition());p.setProductType(d.productType());p.setImageUrl(d.imageUrl());p.setLocation(d.location().trim());if(p.getSeller()==null)p.setSeller(users.get(uid));}public void delete(Long id,Long uid,boolean admin){Product p=get(id);if(!admin&&!p.getSeller().getId().equals(uid))throw new IllegalArgumentException("You can delete only your own products");products.delete(p);}}
